use std::io::{Error, ErrorKind, Result};
use tokio::io::{AsyncReadExt, BufReader};
use tokio::net::TcpStream;
use tokio::sync::{mpsc, watch};

const MAX_FRAME_LEN: usize = 64 * 1024;

async fn frame_reader_task(mut r: BufReader<TcpStream>, tx: mpsc::Sender<Result<Vec<u8>>>) {
    loop {
        let len = match r.read_u32().await {
            Ok(n) => n as usize,
            Err(e) => {
                let _ = tx.send(Err(e)).await;
                break;
            }
        };
        if len > MAX_FRAME_LEN {
            let _ = tx
                .send(Err(Error::new(ErrorKind::InvalidData, "frame too large")))
                .await;
            break;
        }
        let mut buf = vec![0u8; len];
        if let Err(e) = r.read_exact(&mut buf).await {
            let _ = tx.send(Err(e)).await;
            break;
        }
        if tx.send(Ok(buf)).await.is_err() {
            break;
        }
    }
}

pub async fn mux_loop(r: BufReader<TcpStream>, mut shutdown: watch::Receiver<bool>) -> Result<()> {
    let (tx, mut rx) = mpsc::channel::<Result<Vec<u8>>>(32);
    tokio::spawn(frame_reader_task(r, tx));

    loop {
        tokio::select! {
            maybe_frame = rx.recv() => {
                match maybe_frame {
                    Some(Ok(_frame)) => {}
                    Some(Err(e)) => return Err(e),
                    None => break,
                }
            }
            _ = shutdown.changed() => break,
        }
    }
    Ok(())
}
