package artifacts

import (
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

const rootDir = "/srv/artifacts"

func ServeArtifact(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("file")
	if name == "" {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	realRoot, err := filepath.EvalSymlinks(rootDir)
	if err != nil {
		http.Error(w, "server error", http.StatusInternalServerError)
		return
	}
	candidate := filepath.Join(realRoot, filepath.Clean("/"+name))
	realTarget, err := filepath.EvalSymlinks(candidate)
	if err != nil {
		http.NotFound(w, r)
		return
	}
	if !strings.HasPrefix(realTarget, realRoot+string(filepath.Separator)) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	info, err := os.Stat(realTarget)
	if err != nil || !info.Mode().IsRegular() {
		http.NotFound(w, r)
		return
	}
	http.ServeFile(w, r, realTarget)
}
