import type { Pool } from "pg";

export async function rotateRefreshToken(
  db: Pool,
  tokenHash: string,
  issueNewPair: (db: Pool, userId: string, familyId: string) => Promise<{ access: string; refresh: string }>,
) {
  const claimed = await db.query(
    `UPDATE refresh_tokens
     SET used_at = now()
     WHERE token_hash = $1
       AND used_at IS NULL
       AND revoked_at IS NULL
       AND expires_at > now()
     RETURNING user_id, family_id`,
    [tokenHash],
  );

