```go
package auth

import (
	"context"
	"sync"
	"time"

	"golang.org/x/sync/singleflight"
)

type KeyCache struct {
	mu        sync.RWMutex
	sf        singleflight.Group
	expiresAt time.Time
	keys      map[string][]byte
	fetch     func(context.Context) (map[string][]byte, error)
}

func (c *KeyCache) Get(ctx context.Context, kid string) ([]byte, error) {
	c.mu.RLock()
	if time.Now().Before(c.expiresAt) {
		v := c.keys[kid]
		c.mu.RUnlock()
		return v, nil
	}
	c.mu.RUnlock()

	_, err, _ := c.sf.Do("jwks-refresh", func() (any, error) {
		c.mu.RLock()
		stillValid := time.Now().Before(c.expiresAt)
		c.mu.RUnlock()
		if stillValid {
			return nil, nil
		}

		reqCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
		defer cancel()
		fresh, err := c.fetch(reqCtx)
		if err != nil {
			return nil, err
		}

		c.mu.Lock()
		c.keys = fresh
		c.expiresAt = time.Now().Add(5 * time.Minute)
		c.mu.Unlock()
		return nil, nil
	})
	if err != nil {
		return nil, err
	}

	c.mu.RLock()
	v := c.keys[kid]
	c.mu.RUnlock()
	return v, nil
}
```

