async function sha256Hex(input: string): Promise<string> {
  const bytes = new TextEncoder().encode(input);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, "0")).join("");
}

export default {
  async fetch(request: Request, _env: unknown, ctx: ExecutionContext): Promise<Response> {
    const auth = request.headers.get("Authorization")?.trim() ?? "";
    if (request.method !== "GET" || !auth) {
      return fetch(request);
    }

    const cache = caches.default;
    const authDigest = await sha256Hex(auth);
    const keyUrl = new URL(request.url);
    keyUrl.searchParams.set("__edge_auth_scope", authDigest);
    const cacheKey = new Request(keyUrl.toString(), { method: "GET" });

    const cached = await cache.match(cacheKey);
    if (cached) {
      const out = new Response(cached.body, cached);
      out.headers.set("Cache-Control", "private, no-store");
      out.headers.set("Vary", "Authorization");
      return out;
    }

    const originRes = await fetch(request);
    if (originRes.status !== 200 || originRes.headers.has("Set-Cookie")) {
      return originRes;
    }

    const edgeCopy = new Response(originRes.body, originRes);
    edgeCopy.headers.set("Cache-Control", "public, s-maxage=30");
    ctx.waitUntil(cache.put(cacheKey, edgeCopy.clone()));

    const clientRes = new Response(edgeCopy.body, edgeCopy);
    clientRes.headers.set("Cache-Control", "private, no-store");
    clientRes.headers.set("Vary", "Authorization");
    return clientRes;
  },
};
