#include <cstddef>
#include <cstdint>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <unistd.h>
#include <vector>

enum class DrainStatus { Ok, PeerClosed, FatalError };

DrainStatus drain_socket(int epfd, int fd, std::vector<uint8_t>& out, size_t max_buffered = 1u << 20) {
    uint8_t buf[4096];
    while (true) {
        ssize_t n = ::recv(fd, buf, sizeof(buf), 0);
        if (n > 0) {
            if (out.size() + static_cast<size_t>(n) > max_buffered) {
                ::epoll_ctl(epfd, EPOLL_CTL_DEL, fd, nullptr);
                ::close(fd);
                return DrainStatus::FatalError;
            }
            out.insert(out.end(), buf, buf + n);
            continue;
        }
        if (n == 0) {
            ::epoll_ctl(epfd, EPOLL_CTL_DEL, fd, nullptr);
            ::close(fd);
            return DrainStatus::PeerClosed;
        }
        if (errno == EINTR) {
            continue;
        }
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return DrainStatus::Ok;
        }
        ::epoll_ctl(epfd, EPOLL_CTL_DEL, fd, nullptr);
        ::close(fd);
        return DrainStatus::FatalError;
    }
}
