use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::{OnceCell, RwLock};
use tokio::time::{timeout, Duration};

pub struct Conn;
async fn connect_mtls(_addr: &str) -> Result<Arc<Conn>, String> {
    Ok(Arc::new(Conn))
}

pub struct BrokerPool {
    slots: RwLock<HashMap<String, Arc<OnceCell<Arc<Conn>>>>>,
}

impl BrokerPool {
    pub fn new() -> Self {
        Self {
            slots: RwLock::new(HashMap::new()),
        }
    }

    pub async fn get_or_connect(&self, addr: &str) -> Result<Arc<Conn>, String> {
        let cell = {
            let read_guard = self.slots.read().await;
            if let Some(existing) = read_guard.get(addr) {
                Arc::clone(existing)
            } else {
                drop(read_guard);
                let mut write_guard = self.slots.write().await;
                Arc::clone(
                    write_guard
                        .entry(addr.to_owned())
                        .or_insert_with(|| Arc::new(OnceCell::new())),
                )
            }
        };

        let conn = cell
            .get_or_try_init(|| async {
                timeout(Duration::from_secs(5), connect_mtls(addr))
                    .await
                    .map_err(|_| "mTLS connect timed out".to_string())?
            })
            .await?;
        Ok(Arc::clone(conn))
    }
}
