type State struct {
	LastID   int64 `json:"last_id"`
	PageSize int   `json:"page_size"`
	ExpUnix  int64 `json:"exp"`
}

func buildAAD(userID, endpoint string) []byte {
	return []byte(fmt.Sprintf("cursor:v1:%d:%s:%d:%s", len(userID), userID, len(endpoint), endpoint))
