func SealCursor(gcm cipher.AEAD, userID, endpoint string, lastID int64, pageSize int, ttl time.Duration) ([]byte, error) {
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	raw, err := json.Marshal(State{
		LastID:   lastID,
		PageSize: min(max(pageSize, 1), 100),
		ExpUnix:  time.Now().Add(ttl).Unix(),
	})
	if err != nil {
		return nil, err
	}
	return gcm.Seal(nonce, nonce, raw, buildAAD(userID, endpoint)), nil
}

func OpenCursor(gcm cipher.AEAD, userID, endpoint string, token []byte) (State, error) {
	ns := gcm.NonceSize()
	if len(token) < ns+gcm.Overhead() {
		return State{}, errors.New("cursor too short")
	}
	plain, err := gcm.Open(nil, token[:ns], token[ns:], buildAAD(userID, endpoint))
	if err != nil {
		return State{}, errors.New("cursor authentication failed")
	}
	var st State
	if err := json.Unmarshal(plain, &st); err != nil {
		return State{}, err
	}
	if time.Now().Unix() > st.ExpUnix {
		return State{}, errors.New("cursor expired")
	}
	return st, nil
