package gateway

import (
	"net"
	"net/http/httputil"
	"net/netip"
	"net/url"
)

func isTrustedPeer(remoteAddr string, trusted []netip.Prefix) bool {
	host, _, err := net.SplitHostPort(remoteAddr)
	if err != nil {
		return false
	}
	ip, err := netip.ParseAddr(host)
	if err != nil {
		return false
	}
	for _, pfx := range trusted {
		if pfx.Contains(ip) {
			return true
		}
	}
	return false
}

func NewEdgeProxy(target *url.URL, trustedCIDRs []netip.Prefix) *httputil.ReverseProxy {
	return &httputil.ReverseProxy{
		Rewrite: func(pr *httputil.ProxyRequest) {
			pr.SetURL(target)
			pr.Out.Host = pr.In.Host
			pr.Out.Header.Del("X-Real-IP")
			pr.Out.Header.Del("Forwarded")
			if isTrustedPeer(pr.In.RemoteAddr, trustedCIDRs) {
				pr.Out.Header["X-Forwarded-For"] = pr.In.Header["X-Forwarded-For"]
			}
			pr.SetXForwarded()
			if host, _, err := net.SplitHostPort(pr.In.RemoteAddr); err == nil {
