import crypto from "crypto";

export function signCursor(secret: string, tenantId: string, filter: string, lastId: string): string {
  const raw = `${tenantId}:${filter}:${lastId}`;
  const mac = crypto.createHmac("sha256", secret).update(raw).digest("hex");
  return Buffer.from(`${raw}:${mac}`).toString("base64url");
}

export function verifyCursor(secret: string, tenantId: string, filter: string, token: string): string {
  const decoded = Buffer.from(token, "base64url").toString("utf8");
  const [t, f, lastId, mac] = decoded.split(":");
  const expected = crypto.createHmac("sha256", secret).update(`${t}:${f}:${lastId}`).digest("hex");
  if (t !== tenantId || f !== filter || mac !== expected) throw new Error("Invalid cursor");
  return lastId;
}
