```ts
import crypto from "crypto";

export function signCursor(
  secret: Buffer,
  tenantId: string,
  filter: string,
  lastId: string
): string {
  const payload = Buffer.from(
    JSON.stringify([tenantId, filter, lastId]),
    "utf8"
  ).toString("base64url");
  const sig = crypto.createHmac("sha256", secret).update(payload).digest("base64url");
  return `${payload}.${sig}`;
}

export function verifyCursor(
  secret: Buffer,
  expectedTenantId: string,
  expectedFilter: string,
  token: string
): string {
  const dot = token.indexOf(".");
  if (dot <= 0 || dot !== token.lastIndexOf(".")) {
    throw new Error("Malformed cursor");
  }
  const payload = token.slice(0, dot);
  const sigBuf = Buffer.from(token.slice(dot + 1), "base64url");
  const expectedSig = crypto.createHmac("sha256", secret).update(payload).digest();

  if (sigBuf.length !== expectedSig.length || !crypto.timingSafeEqual(sigBuf, expectedSig)) {
    throw new Error("Invalid cursor signature");
  }

  const parsed: unknown = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
  if (
    !Array.isArray(parsed) ||
    parsed.length !== 3 ||
    parsed[0] !== expectedTenantId ||
    parsed[1] !== expectedFilter ||
    typeof parsed[2] !== "string"
  ) {
    throw new Error("Cursor context mismatch");
  }
  return parsed[2];
}
