const BPS_SCALE = 10_000n;

export function applyDiscountBps(subtotalCents: bigint, discountBps: bigint): bigint {
  if (subtotalCents < 0n) {
    throw new RangeError("subtotalCents must be non-negative");
  }
  if (discountBps < 0n || discountBps > BPS_SCALE) {
    throw new RangeError("discountBps must be between 0 and 10000");
