use hmac::{Hmac, Mac};
use sha2::Sha256;
use std::time::{SystemTime, UNIX_EPOCH};

const MAX_SKEW_SECS: i64 = 300;

pub fn verify_webhook(
    secret: &[u8],
    timestamp_hdr: &str,
    sig_hex: &str,
    body: &[u8],
) -> bool {
    let Ok(ts) = timestamp_hdr.parse::<i64>() else {
        return false;
