  const workerCount = Math.max(1, Math.min(concurrency, 64, customerIds.length));
  if (workerCount === 0) {
    return;
  }

  let nextIndex = 0;
  let failed = false;

  async function worker(): Promise<void> {
    while (!failed) {
      signal?.throwIfAborted();
      const idx = nextIndex++;
      if (idx >= customerIds.length) {
        return;
      }
      try {
        await syncOne(customerIds[idx], signal);
      } catch (err) {
        failed = true;
        throw err;
      }
    }
  }

  await Promise.all(Array.from({ length: workerCount }, () => worker()));
}
