const ALLOWED_ASSET_HOSTS = new Set(["cdn.example.com", "media.example.com"]);

export async function proxyAsset(req: Request): Promise<Response> {
  if (req.method !== "GET" && req.method !== "HEAD") {
    return new Response("Method Not Allowed", { status: 405 });
  }

  const rawSrc = new URL(req.url).searchParams.get("src");
  if (!rawSrc) {
    return new Response("Missing src", { status: 400 });
  }

  let target: URL;
  try {
    target = new URL(rawSrc);
  } catch {
    return new Response("Invalid URL", { status: 400 });
  }

  if (
    target.protocol !== "https:" ||
    target.username !== "" ||
    target.password !== "" ||
    (target.port !== "" && target.port !== "443") ||
    !ALLOWED_ASSET_HOSTS.has(target.hostname.toLowerCase())
  ) {
    return new Response("Forbidden upstream", { status: 403 });
  }

  const cleanHeaders = new Headers();
  const accept = req.headers.get("Accept");
  if (accept) {
    cleanHeaders.set("Accept", accept);
  }

  return fetch(target.toString(), {
    method: req.method,
    headers: cleanHeaders,
    redirect: "error",
  });
}
