package billing

import (
	"errors"
	"math/big"
)

func ProrateCents(planCents, usedSecs, periodSecs int64) (int64, error) {
	if planCents < 0 || periodSecs <= 0 {
		return 0, errors.New("invalid planCents or periodSecs")
	}
	if usedSecs <= 0 || planCents == 0 {
		return 0, nil
	}
	if usedSecs >= periodSecs {
		return planCents, nil
	}

	num := new(big.Int).Mul(big.NewInt(planCents), big.NewInt(usedSecs))
	den := big.NewInt(periodSecs)
	quot, rem := new(big.Int).QuoRem(num, den, new(big.Int))

	twiceRem := new(big.Int).Lsh(rem, 1)
	cmp := twiceRem.Cmp(den)
	if cmp > 0 || (cmp == 0 && quot.Bit(0) == 1) {
		quot.Add(quot, big.NewInt(1))
	}
	return quot.Int64(), nil
}
