CREATE OR REPLACE FUNCTION verify_journal_entry_balanced()
RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    net_diff bigint;
BEGIN
    SELECT COALESCE(SUM(debit_cents) - SUM(credit_cents), 0)
