```cpp
#include <chrono>
#include <condition_variable>
#include <deque>
#include <mutex>
#include <optional>
#include <utility>

template <typename Conn>
class ConnPool {
    std::mutex mu_;
    std::condition_variable cv_;
    std::deque<Conn> idle_;
    bool closed_ = false;

public:
    std::optional<Conn> acquire(std::chrono::milliseconds timeout) {
        std::unique_lock<std::mutex> lock(mu_);
        const bool ready = cv_.wait_for(lock, timeout, [this] {
            return closed_ || !idle_.empty();
        });
        if (!ready || closed_ || idle_.empty()) {
            return std::nullopt;
        }
        Conn c = std::move(idle_.front());
        idle_.pop_front();
        return c;
    }

    void release(Conn c) {
        {
            std::lock_guard<std::mutex> lock(mu_);
            if (closed_) {
                return;
            }
            idle_.push_back(std::move(c));
        }
        cv_.notify_one();
    }

    void shutdown() {
        {
            std::lock_guard<std::mutex> lock(mu_);
            closed_ = true;
            idle_.clear();
        }
        cv_.notify_all();
    }
};
