const ALLOWED_WS_ORIGINS = new Set(["https://console.example.com"]);
const MAX_FRAME_BYTES = 32 * 1024;

export function handleWsUpgrade(
  req: Request,
  forwardToNats: (payload: string) => void,
): Response {
  if (req.headers.get("Upgrade")?.toLowerCase() !== "websocket") {
    return new Response("Expected websocket", { status: 426 });
  }
  const origin = req.headers.get("Origin") ?? "";
  if (!ALLOWED_WS_ORIGINS.has(origin)) {
    return new Response("Forbidden origin", { status: 403 });
  }

  const pair = new WebSocketPair();
  const [client, server] = [pair[0], pair[1]];
  server.accept();

  const encoder = new TextEncoder();
  server.addEventListener("message", (ev) => {
    if (typeof ev.data !== "string") {
      server.close(1003, "Text frames only");
      return;
    }
    if (encoder.encode(ev.data).byteLength > MAX_FRAME_BYTES) {
      server.close(1009, "Frame too large");
      return;
    }
    forwardToNats(ev.data);
  });

  return new Response(null, { status: 101, webSocket: client });
}
