#include <condition_variable>
#include <cstddef>
#include <deque>
#include <mutex>
#include <unistd.h>

class SocketQueue {
    std::mutex mu_;
    std::condition_variable cv_;
    std::deque<int> fds_;
    size_t capacity_;
    bool closed_ = false;

public:
    explicit SocketQueue(size_t capacity = 256) : capacity_(capacity) {}

    bool push(int fd) {
        {
            std::lock_guard<std::mutex> lk(mu_);
            if (closed_ || fds_.size() >= capacity_) {
                return false;
            }
            fds_.push_back(fd);
        }
        cv_.notify_one();
        return true;
    }

    int pop() {
        std::unique_lock<std::mutex> lk(mu_);
        cv_.wait(lk, [this] { return !fds_.empty() || closed_; });
        if (fds_.empty()) {
            return -1;
        }
        int fd = fds_.front();
        fds_.pop_front();
        return fd;
    }

    void shutdown() {
        std::deque<int> to_close;
        {
            std::lock_guard<std::mutex> lk(mu_);
            closed_ = true;
            to_close.swap(fds_);
        }
        cv_.notify_all();
        for (int fd : to_close) {
            ::close(fd);
        }
    }
};
