#include <cstddef>
#include <string>
#include <string_view>
#include <vector>

static bool split_amqp_key(std::string_view input, std::vector<std::string_view>& tokens) {
    if (input.size() > 255) {
        return false;
    }
    tokens.clear();
    if (input.empty()) {
        return true;
    }
    size_t start = 0;
    while (start <= input.size()) {
        if (tokens.size() >= 32) {
            return false;
        }
        const size_t dot = input.find('.', start);
        if (dot == std::string_view::npos) {
            tokens.push_back(input.substr(start));
            break;
        }
        tokens.push_back(input.substr(start, dot - start));
        start = dot + 1;
    }
    return true;
}

bool match_amqp_topic(std::string_view pattern, std::string_view routing_key) {
    std::vector<std::string_view> pat;
    std::vector<std::string_view> key;
    if (!split_amqp_key(pattern, pat) || !split_amqp_key(routing_key, key)) {
        return false;
    }

    const size_t K = key.size();
    std::vector<bool> dp(K + 1, false);
    dp[0] = true;

    for (std::string_view tok : pat) {
        if (tok == "#") {
            for (size_t j = 1; j <= K; ++j) {
                dp[j] = dp[j] || dp[j - 1];
            }
        } else {
            std::vector<bool> next(K + 1, false);
            for (size_t j = 1; j <= K; ++j) {
                if (dp[j - 1] && (tok == "*" || tok == key[j - 1])) {
                    next[j] = true;
                }
            }
            dp.swap(next);
        }
    }
    return dp[K];
}
