use tokio_postgres::Client;

#[derive(Debug)]
pub enum RefundError {
    InvalidAmount,
    InvoiceNotFound,
    ExceedsTotal,
    Db(tokio_postgres::Error),
}

pub async fn issue_refund(
    client: &mut Client,
    invoice_id: i64,
    refund_cents: i64,
) -> Result<(), RefundError> {
    if refund_cents <= 0 {
        return Err(RefundError::InvalidAmount);
    }

    let tx = client.transaction().await.map_err(RefundError::Db)?;
    let row = tx
        .query_opt(
            "SELECT total_cents, refunded_cents FROM invoices WHERE id = $1 FOR NO KEY UPDATE",
            &[&invoice_id],
        )
        .await
        .map_err(RefundError::Db)?
        .ok_or(RefundError::InvoiceNotFound)?;

