    let refunded_so_far: i64 = row.get(1);
    let new_refunded = refunded_so_far
        .checked_add(refund_cents)
        .ok_or(RefundError::ExceedsTotal)?;
    if new_refunded > total_cents {
        return Err(RefundError::ExceedsTotal);
    }

    tx.execute(
        "UPDATE invoices SET refunded_cents = $1 WHERE id = $2",
        &[&new_refunded, &invoice_id],
    )
    .await
    .map_err(RefundError::Db)?;

    tx.execute(
        "INSERT INTO refund_events (invoice_id, amount_cents) VALUES ($1, $2)",
        &[&invoice_id, &refund_cents],
    )
    .await
    .map_err(RefundError::Db)?;

    tx.commit().await.map_err(RefundError::Db)
}
