export interface WasmFeeExports {
  memory: WebAssembly.Memory;
  dealloc: (ptr: number, len: number) => void;
}

const MAX_WASM_JSON_BYTES = 262_144;
const STRICT_UTF8 = new TextDecoder("utf-8", { fatal: true });

export function readWasmJson(wasm: WasmFeeExports, ptr: number, len: number): unknown {
  if (!Number.isSafeInteger(ptr) || !Number.isSafeInteger(len) || ptr <= 0 || len <= 0) {
    throw new RangeError("Invalid WASM pointer or length");
  }

  const memBytes = wasm.memory.buffer.byteLength;
  if (len > MAX_WASM_JSON_BYTES || ptr + len > memBytes) {
    throw new RangeError("WASM slice out of bounds");
  }

  let text: string;
  try {
    const copy = new Uint8Array(wasm.memory.buffer, ptr, len).slice();
    text = STRICT_UTF8.decode(copy);
  } finally {
    wasm.dealloc(ptr, len);
  }

  return JSON.parse(text);
}
