```ts
interface CachedToken {
  accessToken: string;
  expiresAtMs: number;
}

const EXPIRY_SKEW_MS = 30_000;

export class BrokerTokenProvider {
  private cached: CachedToken | null = null;
  private inFlight: Promise<CachedToken> | null = null;

  constructor(private readonly mintToken: () => Promise<CachedToken>) {}

  async getToken(): Promise<string> {
    const now = Date.now();
    if (this.cached && now + EXPIRY_SKEW_MS < this.cached.expiresAtMs) {
      return this.cached.accessToken;
    }
    if (!this.inFlight) {
      this.inFlight = (async () => {
        try {
          const fresh = await this.mintToken();
          if (!this.cached || fresh.expiresAtMs >= this.cached.expiresAtMs) {
            this.cached = fresh;
          }
          return this.cached;
        } finally {
          this.inFlight = null;
        }
      })();
    }
    const token = await this.inFlight;
    return token.accessToken;
  }
}
