export class AgentLogShipper {
  private queue: string[] = [];
  private inFlight: Promise<void> | null = null;

  constructor(
    private readonly maxQueueSize = 5000,
    private readonly batchSize = 250,
  ) {}

  enqueue(line: string): boolean {
    if (this.queue.length >= this.maxQueueSize) {
      return false;
    }
    this.queue.push(line);
    return true;
  }

  flush(upload: (lines: string[]) => Promise<void>): Promise<void> {
    if (this.inFlight) {
      return this.inFlight;
    }
    this.inFlight = this.drain(upload).finally(() => {
      this.inFlight = null;
    });
    return this.inFlight;
  }

  private async drain(upload: (lines: string[]) => Promise<void>): Promise<void> {
    while (this.queue.length > 0) {
      const batch = this.queue.splice(0, this.batchSize);
      try {
        await upload(batch);
      } catch (err) {
        const room = Math.max(0, this.maxQueueSize - this.queue.length);
        this.queue.unshift(...batch.slice(0, room));
        throw err;
      }
    }
  }
}
```
